import { Course, Module, UserCourseProgress } from "@/types/lms";

// Helper to generate stub modules for courses without detailed content yet
const generateStubModules = (courseId: string, durationStr: string): Module[] => {
    const hours = parseInt(durationStr) || 10;
    const moduleCount = Math.max(3, Math.floor(hours / 2));

    return Array.from({ length: moduleCount }).map((_, i) => ({
        id: `m${i + 1}-${courseId}`,
        title: `Module ${i + 1}: Course Concepts`,
        description: "In-depth exploration of key topics and practical applications.",
        duration: 60,
        lessons: [
            {
                id: `l${i + 1}-1-${courseId}`,
                title: "Core Concepts",
                type: "video",
                duration: 20,
                videoUrl: "https://example.com/placeholder"
            },
            {
                id: `l${i + 1}-2-${courseId}`,
                title: "Reading Materials",
                type: "text",
                duration: 30,
                content: "# Lesson Content\nDetailed course material coming soon."
            },
            {
                id: `l${i + 1}-3-${courseId}`,
                title: "Knowledge Check",
                type: "quiz",
                duration: 10,
                questions: [
                    { id: "q1", question: "Placeholder Question?", options: ["A", "B", "C", "D"], correctAnswer: 0 }
                ]
            }
        ]
    }));
};

